using System;
using System.IO;
using System.Linq;
using System.Drawing;
using System.Drawing.Imaging;
using System.Collections.Generic;

public class FrameReport {
 public int frame, bottom_row, height, width, colors, edge_pixels;
 public double horizontal_center, vertical_center;
 public int[] bbox, source_bbox; public double source_height_relative_to_first;
}
public class SheetReport {
 public string sheet, source;
 public int cell, frames, colors, palette_outside, nonbinary_alpha, edge_pixels;
 public bool passed, scale8_exact;
 public double max_center_drift,max_height_drift;
 public List<FrameReport> measurements=new List<FrameReport>();
 public List<string> errors=new List<string>();
}
public class EnemyProcessor {
 static string[] names={"Goblin_Raider","Imp_Flyer","Skeleton_Archer","Elite_Knight","Orc_Brute"};
 static int[] cells={64,64,96,96,128}, heights={48,44,72,84,96};
 static string[] anims={"Idle","Run","Hit","Death"};
 static int[] counts={4,6,2,6};
 static string[] hex={"19181F","2A282D","3D3940","555058","74666A","8D7B80","B3A1A0","D0BEB8","E7D8CE","47525A","75818A","334629","58783B","88AE43","B8D849","D8EC76","38284D","58377B","8050AD","B581D4"};
 static Color[] pal=hex.Select(s=>ColorTranslator.FromHtml("#"+s)).ToArray();
 static Rectangle Bounds(Bitmap b,Rectangle region) {int l=region.Right,t=region.Bottom,r=-1,bt=-1;for(int y=region.Top;y<region.Bottom;y++)for(int x=region.Left;x<region.Right;x++)if(b.GetPixel(x,y).A>=128){l=Math.Min(l,x);t=Math.Min(t,y);r=Math.Max(r,x);bt=Math.Max(bt,y);}return r<l?Rectangle.Empty:Rectangle.FromLTRB(l,t,r+1,bt+1);}
 static Rectangle Bounds(Bitmap b){return Bounds(b,new Rectangle(0,0,b.Width,b.Height));}
 static Color Quant(Color c){if(c.A<128)return Color.Transparent;int best=0,d0=int.MaxValue;for(int i=0;i<pal.Length;i++){int r=c.R-pal[i].R,g=c.G-pal[i].G,b=c.B-pal[i].B,d=r*r+g*g+b*b;if(d<d0){d0=d;best=i;}}return pal[best];}
 static Bitmap Scale(Bitmap b,int k){Bitmap z=new Bitmap(b.Width*k,b.Height*k);for(int y=0;y<z.Height;y++)for(int x=0;x<z.Width;x++)z.SetPixel(x,y,b.GetPixel(x/k,y/k));return z;}
 static void Paste(Bitmap dst,Bitmap src,int x,int y){using(Graphics g=Graphics.FromImage(dst))g.DrawImageUnscaled(src,x,y);}
 static void Label(Bitmap b,string s,int x,int y){using(Graphics g=Graphics.FromImage(b))using(Font f=new Font("Consolas",10,FontStyle.Regular,GraphicsUnit.Pixel))using(Brush br=new SolidBrush(Color.FromArgb(231,216,206))){g.TextRenderingHint=System.Drawing.Text.TextRenderingHint.SingleBitPerPixelGridFit;g.DrawString(s,f,br,x,y);}}
 // Only remove disconnected specks of at most two pixels; never redraw contours.
 static void Clean(Bitmap b){bool[,] seen=new bool[b.Width,b.Height];for(int y=0;y<b.Height;y++)for(int x=0;x<b.Width;x++){if(seen[x,y]||b.GetPixel(x,y).A==0)continue;List<Point> pts=new List<Point>();Queue<Point> q=new Queue<Point>();q.Enqueue(new Point(x,y));seen[x,y]=true;while(q.Count>0){Point p=q.Dequeue();pts.Add(p);for(int dy=-1;dy<=1;dy++)for(int dx=-1;dx<=1;dx++){int xx=p.X+dx,yy=p.Y+dy;if(xx>=0&&yy>=0&&xx<b.Width&&yy<b.Height&&!seen[xx,yy]&&b.GetPixel(xx,yy).A>0){seen[xx,yy]=true;q.Enqueue(new Point(xx,yy));}}}if(pts.Count<=2)foreach(Point p in pts)b.SetPixel(p.X,p.Y,Color.Transparent);}}
 // Locate empty gutters close to nominal equal cell divisions.
 static Rectangle[] Regions(Bitmap b,int n){int[] cuts=new int[n+1];cuts[n]=b.Width;for(int f=1;f<n;f++){int center=b.Width*f/n,rad=b.Width/n/4,best=center,score=int.MaxValue;for(int x=center-rad;x<=center+rad;x++){int count=0;for(int y=0;y<b.Height;y++)if(b.GetPixel(x,y).A>=128)count++;int value=count*10000+Math.Abs(x-center);if(value<score){score=value;best=x;}}cuts[f]=best;}Rectangle[] r=new Rectangle[n];for(int f=0;f<n;f++)r[f]=Bounds(b,new Rectangle(cuts[f],0,cuts[f+1]-cuts[f],b.Height));return r;}
 static Rectangle[] RegionsRows(Bitmap b,int n,int rows){if(rows==1)return Regions(b,n);List<Rectangle> boxes=new List<Rectangle>();for(int row=0;row<rows;row++){int cut=b.Height/2,bestScore=int.MaxValue;for(int yy=b.Height/3;yy<b.Height*2/3;yy++){int cnt=0;for(int xx=0;xx<b.Width;xx++)if(b.GetPixel(xx,yy).A>=128)cnt++;int score=cnt*10000+Math.Abs(yy-b.Height/2);if(score<bestScore){bestScore=score;cut=yy;}}int y0=row==0?0:cut,y1=row==0?cut:b.Height;using(Bitmap part=b.Clone(new Rectangle(0,y0,b.Width,y1-y0),PixelFormat.Format32bppArgb)){foreach(Rectangle r0 in Regions(part,n/rows)){Rectangle r=r0;r.Y+=y0;boxes.Add(r);}}}return boxes.ToArray();}
 static Bitmap Restore(Bitmap raw,Rectangle box,int cell,int height,bool flying){int h=height,w=(int)Math.Round(box.Width*(double)h/box.Height);if(w>cell-2){double s=(cell-2)/(double)w;w=cell-2;h=Math.Max(1,(int)Math.Round(h*s));}Bitmap crop=new Bitmap(w,h);for(int y=0;y<h;y++)for(int x=0;x<w;x++){int sx=box.X+Math.Min(box.Width-1,(int)((x+.5)*box.Width/w)),sy=box.Y+Math.Min(box.Height-1,(int)((y+.5)*box.Height/h));crop.SetPixel(x,y,Quant(raw.GetPixel(sx,sy)));}Clean(crop);Rectangle bb=Bounds(crop);Bitmap frame=new Bitmap(cell,cell);if(bb.IsEmpty)return frame;int ox=(int)Math.Round((cell-1)/2.0-(bb.Left+bb.Right-1)/2.0),oy=flying?(int)Math.Round((cell-1)/2.0-(bb.Top+bb.Bottom-1)/2.0):cell-bb.Bottom;Paste(frame,crop,ox,oy);crop.Dispose();return frame;}
 static FrameReport Measure(Bitmap b,int f){Rectangle r=Bounds(b);HashSet<int> colors=new HashSet<int>();int edges=0;for(int y=0;y<b.Height;y++)for(int x=0;x<b.Width;x++){Color c=b.GetPixel(x,y);if(c.A>0){colors.Add(c.ToArgb());if(y==0||((x==0||x==b.Width-1)&&y<b.Height-1))edges++;}}return new FrameReport{frame=f+1,bottom_row=r.Bottom-1,height=r.Height,width=r.Width,colors=colors.Count,edge_pixels=edges,horizontal_center=(r.Left+r.Right-1)/2.0,vertical_center=(r.Top+r.Bottom-1)/2.0,bbox=new int[]{r.Left,r.Top,r.Right-1,r.Bottom-1}};}
 // GIF89a with exact shared palette. Clear LZW dictionary every 200 literal
 // pixels so all emitted codes are 9-bit; no external image package needed.
 static void Gif(string path,List<Bitmap> frames,int fps,bool death){using(BinaryWriter w=new BinaryWriter(File.Create(path))){int size=frames[0].Width*3;w.Write(System.Text.Encoding.ASCII.GetBytes("GIF89a"));w.Write((ushort)size);w.Write((ushort)size);w.Write((byte)0xF7);w.Write((byte)0);w.Write((byte)0);for(int i=0;i<256;i++){Color c=i>0&&i<=pal.Length?pal[i-1]:Color.Black;w.Write(c.R);w.Write(c.G);w.Write(c.B);}w.Write(new byte[]{0x21,0xFF,11});w.Write(System.Text.Encoding.ASCII.GetBytes("NETSCAPE2.0"));w.Write(new byte[]{3,1,0,0,0});for(int f=0;f<frames.Count;f++){w.Write(new byte[]{0x21,0xF9,4,9});w.Write((ushort)((int)Math.Round((f+1)*100.0/fps)-(int)Math.Round(f*100.0/fps)));w.Write((byte)0);w.Write((byte)0);w.Write((byte)0x2C);w.Write((ushort)0);w.Write((ushort)0);w.Write((ushort)size);w.Write((ushort)size);w.Write((byte)0);w.Write((byte)8);List<byte> data=new List<byte>();int bits=0,acc=0,count=0;Action<int> code=v=>{acc|=v<<bits;bits+=9;while(bits>=8){data.Add((byte)(acc&255));acc>>=8;bits-=8;}};code(256);for(int y=0;y<size;y++)for(int x=0;x<size;x++){Color c=frames[f].GetPixel(x/3,y/3);int idx=c.A==0?0:Array.FindIndex(pal,p=>p.ToArgb()==c.ToArgb())+1;code(idx);if(++count==200){code(256);count=0;}}code(257);if(bits>0)data.Add((byte)acc);for(int i=0;i<data.Count;i+=255){int len=Math.Min(255,data.Count-i);w.Write((byte)len);w.Write(data.GetRange(i,len).ToArray());}w.Write((byte)0);}w.Write((byte)0x3B);}}
 public static List<SheetReport> Build(string root,string only){List<SheetReport> reports=new List<SheetReport>();Bitmap preview=new Bitmap(960,2300);using(Graphics g=Graphics.FromImage(preview))g.Clear(Color.FromArgb(45,44,52));int py=0;
 for(int i=0;i<names.Length;i++){int ystart=py;int cell=cells[i];using(Bitmap approved=new Bitmap(Path.Combine(root,"..","EnemyConceptV2","_1x",names[i]+"_Concept.png"))){HashSet<int> cp=new HashSet<int>();for(int yy=0;yy<approved.Height;yy++)for(int xx=0;xx<approved.Width;xx++){Color cc=approved.GetPixel(xx,yy);if(cc.A==255)cp.Add(cc.ToArgb());}pal=cp.OrderBy(v=>v).Select(v=>Color.FromArgb(v)).ToArray();}Label(preview,names[i]+" / concept at left",4,py+2);py+=20;for(int a=0;a<anims.Length;a++){string key=names[i]+"_"+anims[a],source=Path.Combine(root,"Sources",key+"_Selected.png");if(!File.Exists(source)||(!String.IsNullOrEmpty(only)&&key!=only)){py+=cell+18;continue;}using(Bitmap raw=new Bitmap(source)){int n=counts[a];Rectangle[] boxes=RegionsRows(raw,n,File.Exists(Path.Combine(root,"Sources",key+"_2rows.txt"))?2:1);foreach(Rectangle box in boxes)if(box.IsEmpty)throw new Exception(key+" empty frame");double referenceH=boxes[0].Height;List<Bitmap> frames=new List<Bitmap>();using(Bitmap sheet=new Bitmap(cell*n,cell)){SheetReport report=new SheetReport{sheet=key,source="Sources/"+key+"_Selected.png",cell=cell,frames=n};HashSet<int> allColors=new HashSet<int>();for(int f=0;f<n;f++){int h=a==3?Math.Max(8,(int)Math.Round(heights[i]*boxes[f].Height/referenceH)):heights[i];h=Math.Min(cell-2,h);Bitmap frame=Restore(raw,boxes[f],cell,h,i==1&&a!=3);if(i==1&&a==3&&f<3){Bitmap moved=new Bitmap(cell,cell);int dy=-(int)Math.Round((cell-heights[i])/2.0*(1-f/3.0));Paste(moved,frame,0,dy);frame.Dispose();frame=moved;}frames.Add(frame);Paste(sheet,frame,f*cell,0);FrameReport fm=Measure(frame,f);fm.source_bbox=new int[]{boxes[f].X,boxes[f].Y,boxes[f].Width,boxes[f].Height};fm.source_height_relative_to_first=boxes[f].Height/referenceH;report.measurements.Add(fm);for(int y=0;y<cell;y++)for(int x=0;x<cell;x++){Color c=frame.GetPixel(x,y);if(c.A>0)allColors.Add(c.ToArgb());if(c.A!=0&&c.A!=255)report.nonbinary_alpha++;}}report.colors=allColors.Count;report.palette_outside=allColors.Count(c=>!pal.Any(p=>p.ToArgb()==c));report.edge_pixels=report.measurements.Sum(m=>m.edge_pixels);double meanX=report.measurements.Average(m=>m.horizontal_center),meanH=report.measurements.Average(m=>m.height);report.max_center_drift=report.measurements.Max(m=>Math.Abs(m.horizontal_center-meanX));report.max_height_drift=report.measurements.Max(m=>Math.Abs(m.height-meanH));if(report.colors>20||report.palette_outside>0)report.errors.Add("palette");if(report.nonbinary_alpha>0)report.errors.Add("alpha");if(report.edge_pixels>0)report.errors.Add("edges");if(i!=1&&report.measurements.Any(m=>m.bottom_row!=cell-1))report.errors.Add("baseline");if(i==1&&a!=3&&report.measurements.Any(m=>Math.Abs(m.vertical_center-cell/2.0)>2))report.errors.Add("flight center");if(a!=3&&(report.max_center_drift>2||report.max_height_drift>2))report.errors.Add("drift");if(a==0&&Math.Abs(report.measurements[0].height-heights[i])>2)report.errors.Add("idle height");sheet.Save(Path.Combine(root,"_1x",key+".png"),ImageFormat.Png);using(Bitmap zoom=Scale(sheet,8)){string dest=Path.Combine(root,"Enemies",key+".png");zoom.Save(dest,ImageFormat.Png);using(Bitmap reloaded=new Bitmap(dest)){report.scale8_exact=reloaded.Width==sheet.Width*8&&reloaded.Height==sheet.Height*8;for(int y=0;y<reloaded.Height&&report.scale8_exact;y++)for(int x=0;x<reloaded.Width;x++)if(reloaded.GetPixel(x,y).ToArgb()!=sheet.GetPixel(x/8,y/8).ToArgb()){report.scale8_exact=false;break;}}}if(!report.scale8_exact)report.errors.Add("8x");report.passed=report.errors.Count==0;reports.Add(report);Label(preview,anims[a],4,py);using(Bitmap concept=new Bitmap(Path.Combine(root,"..","EnemyConceptV2","_1x",names[i]+"_Concept.png")))Paste(preview,concept,0,py+14);Paste(preview,sheet,144,py+14);Console.WriteLine(key+" "+(report.passed?"PASS":"FAIL")+" heights="+String.Join(",",report.measurements.Select(m=>m.height.ToString()).ToArray())+" colors="+report.colors);}
 Gif(Path.Combine(root,"Animations",key+"_3x.gif"),frames,a==0?6:10,a==3);foreach(Bitmap f in frames)f.Dispose();}py+=cell+18;}using(Bitmap block=preview.Clone(new Rectangle(0,ystart,960,py-ystart),PixelFormat.Format32bppArgb))using(Bitmap z=Scale(block,3))z.Save(Path.Combine(root,"Sources","Review_"+names[i]+"_3x.png"),ImageFormat.Png);}
 using(Bitmap cropped=preview.Clone(new Rectangle(0,0,960,Math.Min(py,preview.Height)),PixelFormat.Format32bppArgb))using(Bitmap z=Scale(cropped,3))z.Save(Path.Combine(root,"Preview_3x.png"),ImageFormat.Png);preview.Dispose();return reports;}
}
